          ]
        },
        {
          "proposicao": "A fonte aponta que, na avaliação de sistemas com agentes gasosos, devem ser considerados a taxa de falhas reportada, a possibilidade de disparo acidental e o risco que isso pode representar para as pessoas.",
          "trechos": [
            "Eef130c7163fd60ee:0:700"
